mapper.select:
SELECT DISTINCT PTL_PORTFOLIO.PORTFOLIO_ID id, PTL_PORTFOLIO.PORTFOLIO_ID || ':' || PTL_PORTFOLIO.PORTFOLIO_NAME text, INV_TRANS_PORTF object FROM PTL_PORTFOLIO LEFT JOIN PTL_SEC_ACCT ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_SEC_ACCT.PORTFOLIO_ID
INVEST_YESORNO = 'Y' AND PORTFOLIO_TYPE = '01' AND INV_TRANS_PORTF IS NOT NULL
AND PTL_SEC_ACCT.ACCT_NO = #{secManageAcctId, jdbcType=VARCHAR}
AND (PTL_PORTFOLIO.PORTFOLIO_ID LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%') OR PTL_PORTFOLIO.PORTFOLIO_NAME LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%'))
AND PTL_PORTFOLIO.PORTFOLIO_ID = #{initValue}

SELECT DISTINCT
    B.ACCT_NO as acctNo
FROM
    PTL_CAPACCT_INFO B, STL_CAPACCT_INFO C
WHERE
    B.PORTFOLIO_ID = #{groupId}
    AND B.ACCT_TYPE = #{ACCT_TYPE}
    AND B.CCY = #{ccy}
    AND B.ACCT_NO = C.ACCT_NO
    AND B.CCY = C.CCY

mapper.update:
update PTL_SEC_POSITION
set AMOUNT = AMOUNT - #{amount,jdbcType=DECIMAL}
where PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
  and SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
  and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and BRANCH = #{branch,jdbcType=DECIMAL}
  and INV_AIM = #{invAim,jdbcType=VARCHAR}
  and HODING_TYPE = #{hodingType,jdbcType=VARCHAR}
  and CDATE = #{cdate,jdbcType=DATE}

update PTL_SEC_POSITION_DETAIL
set AMOUNT = AMOUNT - #{amount,jdbcType=DECIMAL}
where PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
  and SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
  and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and BRANCH = #{branch,jdbcType=DECIMAL}
  and TRADE_ID = #{tradeId,jdbcType=VARCHAR}
  and HODING_TYPE = #{hodingType,jdbcType=VARCHAR}
  and CDATE = #{cdate,jdbcType=DATE}
